def transform(grid):
    # Mark background region between top pattern and lower objects; output encodes zero spaces in leading field as 8.
    # Generic heuristic: 4-connected zero components; fill the largest interior zero component with 8.
    from collections import deque
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] or (i,j) in seen: continue
            q=deque([(i,j)]); seen.add((i,j)); c=[]
            while q:
                x,y=q.popleft(); c.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                        seen.add((a,b));q.append((a,b))
            comps.append(c)
    # Pattern's 5s partition the canvas; recolor large background area adjacent to upper objects.
    for c in comps:
        if len(c)>=6 and min(x for x,y in c)<h-2:
            for x,y in c: out[x][y]=8
    return out
